using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "GainStarShardsByDieRewardEventAction", menuName = "Data/BattleSceneSetups/Events/EventActions/GainStarShardsByDieRewardEventAction", order = 0)]
public class GainStarShardsByDieRewardEventAction : GainByDieTierRewardEventAction
{
	protected override Reward[] GetRewards()
	{
		GoldReward goldReward = Object.Instantiate(reward) as GoldReward;
		Reward[] array = new Reward[1];
		goldReward.SetGoldAmount(GetMultiplier() * resourceAmount);
		goldReward.SetGettingGoldOnEventNoDelay(gettingGoldOnEventNoDelay: true);
		goldReward.SetDontGoToEndOfBattleState(value: true);
		array[0] = goldReward;
		return array;
	}

	public override string GetEventButtonResultText(string resultTextID)
	{
		return Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(resultTextID), resourceAmount, diceAmount, diceTier.GetLocalizedDiceTierWithDie()) + "\n" + Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("StarShardsReward_D"), GetMultiplier() * resourceAmount);
	}
}
